tool_input.command:
grep -rn "createServer\|handle(" src; node --input-type=module -e "
import { handle } from './src/api.js';
import { tick } from './src/scheduler.js';
const out = (l) => console.log('DELIVERED:', l);
const ist = handle({ method:'POST', path:'/reminders', body:{ userId:'u1', text:'IST 09:00', at:'2026-03-01T09:00', tzOffsetMin:330 } }).body;
const ny  = handle({ method:'POST', path:'/reminders', body:{ userId:'u2', text:'NY 09:00', at:'2026-03-01T09:00', tzOffsetMin:-300 } }).body;
const bad = handle({ method:'POST', path:'/reminders', body:{ userId:'u3', text:'with seconds', at:'2026-03-01T09:00:00' } });
console.log('IST due_ms', new Date(ist.due_ms).toISOString(), '| NY due_ms', new Date(ny.due_ms).toISOString(), '| bad status', bad.status, 'due_ms', bad.body.due_ms);
for (const t of ['2026-02-28T22:00:00Z','2026-03-01T03:30:00Z','2026-03-01T14:00:00Z','2026-03-01T19:00:00Z']) {
  console.log('tick at', t); await tick(Date.parse(t), { out, formatter:'legacy' });
}
"
